def _csv(header: list[str], rows: list[dict]) -> bytes:
    buf = io.StringIO(newline="")
    w = csv.writer(buf)  # default dialect: CRLF, as the real writers produce
    w.writerow(header)
    for r in rows:
        w.writerow([r.get(c, "") for c in header])
    return buf.getvalue().encode("utf-8")


def _sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _slug(name: str) -> str:
    return "".join(c if c.isalnum() else "-" for c in name.lower()).strip("-")


def _letters(i: int) -> str:
    """0 -> 'aa', 1 -> 'ab': an alphabetic tag, so a seed stays one word with no digit."""
    return "abcdefghijklmnopqrstuvwxyz"[i // 26 % 26] + "abcdefghijklmnopqrstuvwxyz"[i % 26]


def accounts() -> list[dict]:
    seen: set[str] = set()
    out: list[dict] = []
    for i in range(N):
        company = fictionalize.company(f"Comp{_letters(i)} Holdings")
        while company in seen:
            company += " Group"
        seen.add(company)
        person = fictionalize.person(f"Giv{_letters(i)} Fam{_letters(i)}")
        first, _, last = person.partition(" ")
        last = last.replace(" ", "-")
        slug = _slug(company)
        domain = f"{slug}.example"
        assert " " not in first and " " not in last, (first, last)
        level = SIGNAL_LEVEL[i % len(SIGNAL_LEVEL)]
        url = URLS[i % len(URLS)]
        evidence = SENTENCES[i % len(SENTENCES)]
        row = {
            "first": first, "last": last or "Seed", "email": f"{first}.{last or 'seed'}@{domain}".lower(),
            "title": TITLES[i % len(TITLES)], "company": company, "company_domain": domain,
            "city": "Seedtown", "country": COUNTRIES[i % len(COUNTRIES)],
            "segment": SEGMENTS[i % len(SEGMENTS)], "tier": TIERS[i % len(TIERS)],
            "score": str(3 + (i * 7) % 10), "conf": str(50 + (i * 3) % 50), "email_status": "valid",
            "why_now": WHY_NOW[i % len(WHY_NOW)], "case_study": "", "src": "seed",
            "conf_tier": "high", "heat": HEATS[i % len(HEATS)],
            "top_intent_score": str((i * 11) % 100) if i % 3 == 0 else "",
            "intent_topics": "agents;routing" if i % 3 == 0 else "",
            "cohort": COHORTS[i % len(COHORTS)], "qualification_path": "signal" if i % 4 else "fit",
            "verdict": VERDICTS[i % len(VERDICTS)],
            "verdict_reason": "thin evidence" if VERDICTS[i % len(VERDICTS)] in ("re-angle", "drop") else "",
            "signal_agent_kind": AGENT_KINDS[i % len(AGENT_KINDS)],
            "category_relation": "prospect" if i % 9 else "partner",
            "industry": INDUSTRIES[i % len(INDUSTRIES)],
            "lane": LANES_IN_POOL[i % len(LANES_IN_POOL)],
            "intent_feeds": "feed-a" if i % 3 == 0 else "",
            "new_in_role": "true" if i % 5 == 0 else "",
            "_level": level, "_url": url, "_evidence": evidence, "_slug": slug,
        }  # fmt: skip
        if level in ("full", "partial"):
            row["signal_source_url"] = url
            row["signal_observed"] = f"2026-09-{1 + i % 18:02d}"
            row["signal_subject"] = company
        if level == "full":
            row["signal_evidence"] = evidence
            row["signal_clause"] = evidence.split(" in ")[0].lower()
        out.append(row)
    return out


def _e_row(a: dict, layout: str) -> dict:
    r = {
        "First Name": a["first"], "Last Name": a["last"], "Email": a["email"],
        "Email Status": a["email_status"], "Job Title": a["title"], "Company Name": a["company"],
        "Company Domain Name": a["company_domain"], "City": a["city"], "Country/Region": a["country"],
        "GTM_Segment": a["segment"], "GTM_Score": a["score"], "GTM_Tier": a["tier"],
        "GTM_Persona_Tier": a["cohort"], "GTM_Why_Now": a["why_now"], "GTM_Source": "seed",
        "GTM_Run_Date": "2026-09-19", "GTM_Rubric_Version": "seed-v1", "GTM_Heat": a["heat"],
        "GTM_Intent_Feeds": a["intent_feeds"], "GTM_Top_Intent_Score": a["top_intent_score"],
        "GTM_Intent_Topics": a["intent_topics"], "GTM_Industry": a["industry"],
        "GTM_New_In_Role": a["new_in_role"], "GTM_Qualification_Path": a["qualification_path"],
        "conf": a["conf"], "GTM_Signal_Source_URL": a.get("signal_source_url", ""),
        "GTM_Signal_Observed": a.get("signal_observed", ""),
        "GTM_Signal_Evidence": a.get("signal_evidence", ""),
        "GTM_Signal_Subject": a.get("signal_subject", ""),
        "GTM_Signal_Agent_Kind": a["signal_agent_kind"], "GTM_Category_Relation": a["category_relation"],
        "GTM_Verdict": a["verdict"], "GTM_Verdict_Reason": a["verdict_reason"],
    }  # fmt: skip
    return r


