def build(out: Path = OUT) -> dict[str, bytes]:
    """Every corpus file as ``{relative path: bytes}``; ``write`` puts them on disk."""
    # `* text=auto eol=lf` at the repo root would rewrite the CSVs' CRLF on commit; the corpus must
    # be byte-exact, like the real writers' output.
    files: dict[str, bytes] = {".gitattributes": b"* -text\n"}
    for rel, text in PROFILE_FILES.items():
        files[f"profiles/{PROFILE}/{rel}"] = text.encode()

    rows = accounts()
    c = f"state/{PROFILE}"
    p = f"{c}/prospects"

    files[f"{p}/prospects-seed-a-hubspot.csv"] = _csv(E_C, [_e_row(a, "c") for a in rows[:16]])
    files[f"{p}/prospects-seed-b-hubspot.csv"] = _csv(E_B, [_e_row(a, "b") for a in rows[16:26]])

    pool = [{**a, "pool_row_id": f"r-{i:010d}"} for i, a in enumerate(rows[24:], start=24)]
    files[f"{p}/sequences/.pool/master-list.csv"] = _csv(G2, pool)
    files[f"{p}/sequences/.pool/suppression.csv"] = _csv(
        ["email", "name", "company_domain", "reason", "date", "note"],
        [
            {"email": rows[3]["email"], "name": "", "company_domain": rows[3]["company_domain"],
             "reason": "unsubscribed", "date": "2026-09-01", "note": "fixture"},
            {"email": rows[30]["email"], "name": "", "company_domain": rows[30]["company_domain"],
             "reason": "bounced", "date": "2026-09-02", "note": "fixture"},
        ],
    )  # fmt: skip
    items = [
        {
            "account_id": f"a-{i:06d}", "id": f"a-{i:06d}", "company": a["company"],
            "domain": a["company_domain"], "status": "active" if i % 11 else "engaged",
            "segment": a["segment"], "tier": a["tier"], "score": a["score"],
            "industry": a["industry"],
        }
        for i, a in enumerate(rows)
    ]  # fmt: skip
    files[f"{p}/latest.json"] = (
        json.dumps({"schema": 1, "items": items}, indent=2, sort_keys=True) + "\n"
    ).encode()
    files[f"{c}/history.jsonl"] = (
        json.dumps(
            {"event": "optout_detected", "email": rows[5]["email"], "ts": "2026-09-10T00:00:00Z"}
        )
        + "\n"
    ).encode()

    # Captures: one per URL with a fixed fetched_at, written chronologically.
    sources = f"{c}/sources"
    index = []
    for url, sentence in zip(URLS, SENTENCES, strict=True):
        text = f"# Notes\n\n{sentence}\n\nMore context follows on the next line.\n"
        sha = _sha(text)
        files[f"{sources}/{sha}.txt"] = text.encode()
        norm = url.rstrip("/").lower()
        index.append(
            json.dumps({"url_norm": norm, "fetched_at": FETCHED_AT, "sha256": sha, "tool": "seed"})
        )
    files[f"{sources}/index.jsonl"] = ("\n".join(index) + "\n").encode()

    for a in rows[:20]:
        files[f"{c}/accounts/{a['_slug']}/account-dossier-2026-09-01.md"] = (
            f"# Dossier: {a['company']}\n\nFixture dossier.\n".encode()
        )

    # Sequences: one enrolled file per lane, registered in cells.toml.
    seq = f"{p}/sequences"
    enrolled_cols = ["email", "Email", "first", "First Name", "last", "Last Name", "company",
                     "Company", "cell_id", "segment", "seat", "title"]  # fmt: skip
    cells = []
    for k, lane in enumerate(["personalised", "generic", "repair", "hold", "excluded"]):
        members = rows[k * 3 : k * 3 + 3]
        cols = (
            enrolled_cols
            + (["why_now", "Why Now"] if lane == "personalised" else [])
            + ["country", "signal_clause", "suppression"]
        )
        data = [
            {"email": m["email"], "Email": m["email"], "first": m["first"], "First Name": m["first"],
             "last": m["last"], "Last Name": m["last"], "company": m["company"],
             "Company": m["company"], "cell_id": f"cell-{lane}", "segment": m["segment"],
             "seat": "platform", "title": m["title"], "why_now": m["why_now"], "Why Now": m["why_now"],
             "country": m["country"], "signal_clause": m.get("signal_clause", ""),
             "suppression": "unsubscribed" if m["email"] == rows[3]["email"] else ""}
            for m in members
        ]  # fmt: skip
        files[f"{seq}/SEQ-{lane}-enrolled.csv"] = _csv(cols, data)
        files[f"{seq}/SEQ-{lane}.md"] = f"# spec {lane}\n\nSign-off: Sam\n".encode()
        cells.append(
            f'[[sequence]]\nid = "SEQ-{lane}"\ncsv = "SEQ-{lane}-enrolled.csv"\n'
            f'spec = "SEQ-{lane}.md"\nlane = "{lane}"\ntitle = "{lane} fixture"\n'
        )
    files[f"{seq}/cells.toml"] = ("\n".join(cells)).encode()

    # The three historical pool layouts, one list each, for the integrity audit. Rows 14-25 mix
    # accounts with and without a dossier. gen3 has four variants because the audit refuses a list
    # whose own lane column disagrees with --lane: blank, routed-generic, routed-personalised, mixed.
    def sample(lane_of) -> list[dict]:
        return [
            {**a, "pool_row_id": f"r-{i:010d}", "lane": lane_of(i, a)}
            for i, a in enumerate(rows[14:26], start=14)
        ]

    files["lists/gen1.csv"] = _csv(G1, sample(lambda i, a: ""))
    files["lists/gen2.csv"] = _csv(G2, sample(lambda i, a: ""))
    files["lists/gen3.csv"] = _csv(G3, sample(lambda i, a: ""))
    files["lists/gen3-generic.csv"] = _csv(G3, sample(lambda i, a: "generic"))
    files["lists/gen3-personalised.csv"] = _csv(G3, sample(lambda i, a: "personalised"))
    files["lists/gen3-mixed.csv"] = _csv(G3, sample(lambda i, a: LANES_IN_POOL[i % 5] or "generic"))

    # Inputs for the render lint, groundedness, score_prospects and the export.
    lint_cols = ["first", "last", "email", "company", "company_domain", "title", "city", "country",
                 "segment", "industry", "signal_clause", "why_now", "signal_evidence",
                 "signal_kind", "signal_observed", "signal_source_url", "suppression"]  # fmt: skip
    files["lists/lint.csv"] = _csv(
        lint_cols,
        [
            {**a, "signal_kind": "event", "suppression": "unsubscribed" if i == 3 else ""}
            for i, a in enumerate(rows)
        ],
    )
    touch = (
        "**Step 1 — Day 0**\n\nSubject: `{{Company}} and its agents`\n\n"
        "> Hi {{First Name}},\n>\n> {{Why Now}} We help teams like {{Company}} record each agent action.\n"
        ">\n> Worth a short call?\n>\n> Sam\n"
    )
    for name, premise in (
        ("relay", "relay-premise"),
        ("seat", "seat-premise"),
        ("unknown", "no-such-premise"),
    ):
        files[f"lists/spec-{name}.md"] = f"Sign-off: Sam\npremise: {premise}\n\n{touch}".encode()
    items = [
        {
            "segment": a["segment"], "company": a["company"], "domain": a["company_domain"],
            "fit_score": int(a["score"]), "intent_feeds": ["feed-a"] if a["intent_feeds"] else [],
            "top_intent_score": int(a["top_intent_score"] or 0),
            "new_in_role": a["new_in_role"] == "true", "verdict": a["verdict"] if a["verdict"] in ("send", "re-angle", "drop") else "",
            "signal_observed": a.get("signal_observed", ""),
        }
        for a in rows
    ]  # fmt: skip
    files["lists/score-items.json"] = (json.dumps(items, indent=2, sort_keys=True) + "\n").encode()

    # The fixture's hook-matrix.md is generated by the code under test; it is not shipped here.
    return files


def write(out: Path = OUT) -> list[Path]:
    if out.exists():
        shutil.rmtree(out)  # the corpus is wholly generated; a stale file would outlive its builder
    written = []
    for rel, data in sorted(build(out).items()):
        path = out / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
        written.append(path)
    return written


if __name__ == "__main__":
    paths = write()
    print(f"wrote {len(paths)} corpus files under {OUT}")
